package com.vaibhav.ediflow.order.api;

import com.vaibhav.ediflow.order.domain.*;import com.vaibhav.ediflow.order.repository.*;import com.vaibhav.ediflow.order.service.DeadLetterService;import org.springframework.data.domain.*;import org.springframework.data.web.PageableDefault;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.util.*;
@RestController @RequestMapping("/api/v1") public class OperationsController {private final DeadLetterService deadLetters;private final PartnerRepository partners;private final EdiInterchangeRepository interchanges;public OperationsController(DeadLetterService d,PartnerRepository p,EdiInterchangeRepository i){deadLetters=d;partners=p;interchanges=i;}@GetMapping("/dead-letters")public Page<DeadLetterView> deadLetters(@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC)Pageable p){return deadLetters.list(p).map(DeadLetterView::from);}@PostMapping("/dead-letters/{id}/retry")public DeadLetterView retry(@PathVariable UUID id){return DeadLetterView.from(deadLetters.retry(id));}@GetMapping("/partners")public List<PartnerView> partners(){return partners.findAll().stream().map(PartnerView::from).toList();}@PostMapping("/partners/{id}/approve")@Transactional public PartnerView approve(@PathVariable UUID id){Partner p=partners.findById(id).orElseThrow(()->new NotFound("Partner not found."));p.activate();return PartnerView.from(p);}@GetMapping("/interchanges")public Page<InterchangeView> interchanges(@RequestParam(required=false)InterchangeStatus status,@PageableDefault(size=20,sort="receivedAt",direction=Sort.Direction.DESC)Pageable p){Page<EdiInterchange> page=status==null?interchanges.findAll(p):interchanges.findByStatus(status,p);return page.map(InterchangeView::from);}record DeadLetterView(UUID id,String sourceTopic,String partnerCode,String errorReason,int retryCount,DeadLetterStatus status,Instant createdAt){static DeadLetterView from(DeadLetterRecord r){return new DeadLetterView(r.getId(),r.getSourceTopic(),r.getPartnerCode(),r.getErrorReason(),r.getRetryCount(),r.getStatus(),r.getCreatedAt());}}record PartnerView(UUID id,String code,String name,PartnerStatus status){static PartnerView from(Partner p){return new PartnerView(p.getId(),p.getCode(),p.getName(),p.getStatus());}}record InterchangeView(UUID id,String partnerCode,String isaControlNumber,String stControlNumber,String documentType,InterchangeStatus status,Instant receivedAt){static InterchangeView from(EdiInterchange i){return new InterchangeView(i.getId(),i.getPartner().getCode(),i.getIsaControlNumber(),i.getStControlNumber(),i.getDocumentType().name(),i.getStatus(),i.getReceivedAt());}}}
